public class Vehicle {private int passengers,fuelcap,mpg;public Vehicle(int p,int f,int m){if(p<0||f<=0||m<=0)throw new IllegalArgumentException();passengers=p;fuelcap=f;mpg=m;}public int getPassengers(){return passengers;}public int getFuelcap(){return fuelcap;}public int getMpg(){return mpg;}public void setPassengers(int v){if(v<0)throw new IllegalArgumentException();passengers=v;}public void setFuelcap(int v){if(v<=0)throw new IllegalArgumentException();fuelcap=v;}public void setMpg(int v){if(v<=0)throw new IllegalArgumentException();mpg=v;}public int range(){return fuelcap*mpg;}public double fuelNeeded(int miles){if(miles<0)throw new IllegalArgumentException();return (double)miles/mpg;}}

